//! Items that exist for code generated by `sotu-macros`.
//!
//! Nothing in this module is public API, and it may change in any release.

use crate::Outcome;

/// Marker selecting the hook adapters for functions that take a trailing
/// context parameter.
pub struct WithContext;

/// Marker selecting the hook adapters for functions that take no context
/// parameter.
pub struct WithoutContext;

/// The result of dispatching an event to a single node.
///
/// Extends [`Outcome`] with the offsets that mounted child machines need to
/// report where a transition is handled or where dispatch continues.
#[derive(Eq, PartialEq, Debug)]
pub enum NodeOutcome<S, X> {
    /// Consume the event.
    Handled,
    /// Defer the event to the parent node.
    Super,
    /// Transition locally to the target.
    Transition(S),
    /// Transition externally to the target.
    ///
    /// `handler_offset` is the number of levels above the visited node at
    /// which the handling node sits, where `0` is the visited node itself.
    ExternalTransition {
        /// The state to transition to.
        target: S,
        /// Levels between the visited node and the handling node.
        handler_offset: usize,
    },
    /// Leave the machine through the given exit point.
    Exit(X),
    /// Skip nodes and continue dispatch `mount_offset` levels above the
    /// visited node.
    DeferToMount {
        /// Levels between the visited node and the node to continue at.
        mount_offset: usize,
    },
}

impl<S, X> From<Outcome<S, X>> for NodeOutcome<S, X> {
    fn from(outcome: Outcome<S, X>) -> Self {
        match outcome {
            Outcome::Handled => Self::Handled,
            Outcome::Super => Self::Super,
            Outcome::Transition(target) => Self::Transition(target),
            Outcome::ExternalTransition(target) => Self::ExternalTransition {
                target,
                handler_offset: 0,
            },
            Outcome::Exit(exit) => Self::Exit(exit),
        }
    }
}

impl<S, X> NodeOutcome<S, X> {
    /// Map the target of a `Transition` or `ExternalTransition` with `map`.
    ///
    /// All other variants are returned unchanged.
    pub fn map_state<T>(self, map: impl FnOnce(S) -> T) -> NodeOutcome<T, X> {
        match self {
            Self::Handled => NodeOutcome::Handled,
            Self::Super => NodeOutcome::Super,
            Self::Transition(target) => NodeOutcome::Transition(map(target)),
            Self::ExternalTransition {
                target,
                handler_offset,
            } => NodeOutcome::ExternalTransition {
                target: map(target),
                handler_offset,
            },
            Self::Exit(exit) => NodeOutcome::Exit(exit),
            Self::DeferToMount { mount_offset } => NodeOutcome::DeferToMount { mount_offset },
        }
    }
}

/// The mode-neutral view of a generated machine.
///
/// Parent code names a child's types through this trait, as in
/// `<C as Submachine>::State`, regardless of the mode of either machine.
pub trait Submachine: Sized {
    /// The event type handled by the machine.
    type Event;

    /// The context handed to every handler, entry action and exit action.
    type Context<'ctx, 'data: 'ctx>;

    /// The leaf states of the machine.
    type State;

    /// The superstates of the machine, borrowing local storage from the active
    /// leaf state for `'sub`.
    ///
    /// The bound `Self: 'sub` covers every parameter the state type can
    /// mention, because every parameter of an implementation appears in `Self`.
    type Superstate<'sub>
    where
        Self: 'sub;

    /// The exit points through which the machine can be left.
    type Exit;

    /// Return the state the machine starts in.
    fn initial() -> Self::State;
}

/// Marker for generated machines that run in blocking mode.
///
/// A blocking parent requires this trait of its children, so its diagnostic is
/// the one a user sees when mounting an awaitable child.
#[diagnostic::on_unimplemented(
    message = "`{Self}` is an awaitable state machine and can not be mounted in a blocking one",
    note = "add `awaitable` to the parent's `#[state_machine]`"
)]
pub trait BlockingSubmachine: Submachine + crate::blocking::IntoStateMachine {}

/// A [`NodeOutcome`] together with the event it was produced for.
///
/// Dispatch hooks take the event by value so that mount boundaries can move it
/// into a child's event type, and they hand it back through this type.
#[derive(Eq, PartialEq, Debug)]
pub struct Dispatched<S, X, E> {
    /// What the visited node decided to do with the event.
    pub outcome: NodeOutcome<S, X>,
    /// The event that was dispatched.
    pub event: E,
}

// MARK: Mount Fields

/// Access to the parent field that stores a mounted submachine `C`.
///
/// The macro can not see a field's type, so it resolves the storage kind
/// through this trait. A field of type `C` is persistent storage: the child
/// keeps its value across activations of its mount node. A field of type
/// `Option<C>` holds one instance per activation: it is `Some` exactly while
/// its mount node is active and `None` otherwise.
///
/// The two implementations do not overlap even when `C` is itself an
/// `Option`, because the trait parameter differs between them.
#[diagnostic::on_unimplemented(
    message = "field of type `{Self}` can not hold submachine `{C}`",
    note = "a submachine field must have type `{C}` (persistent) or `Option<{C}>` (one instance per activation)"
)]
pub trait MountField<C> {
    /// Borrow the stored submachine, or return `None` if the field holds no
    /// instance.
    ///
    /// A persistent field always returns `Some`. An instance field returns
    /// `Some` exactly while its mount node is active.
    fn get(&self) -> Option<&C>;

    /// Mutably borrow the stored submachine, or return `None` if the field
    /// holds no instance.
    ///
    /// A persistent field always returns `Some`. An instance field returns
    /// `Some` exactly while its mount node is active.
    fn get_mut(&mut self) -> Option<&mut C>;

    /// Release the stored submachine when its mount node is exited.
    ///
    /// An instance field drops its instance and becomes `None`, so it is
    /// `None` whenever its mount node is inactive. A persistent field keeps
    /// its value unchanged.
    fn release(&mut self);
}

impl<C> MountField<C> for C {
    fn get(&self) -> Option<&C> {
        Some(self)
    }

    fn get_mut(&mut self) -> Option<&mut C> {
        Some(self)
    }

    fn release(&mut self) {}
}

impl<C> MountField<C> for Option<C> {
    fn get(&self) -> Option<&C> {
        self.as_ref()
    }

    fn get_mut(&mut self) -> Option<&mut C> {
        self.as_mut()
    }

    fn release(&mut self) {
        *self = None;
    }
}

/// Creation of a default submachine `C` in the parent field that stores it.
///
/// A mount node without a factory fills its field through this trait on
/// entry, so that an instance field of type `Option<C>` is `Some` exactly
/// while its mount node is active. Only instance fields require
/// `C: Default`; a persistent field of type `C` already holds its child.
#[diagnostic::on_unimplemented(
    message = "`{C}` does not implement `Default`",
    note = "declare `factory = …` on `#[submachine]` or store it in a field of type `{C}`"
)]
pub trait DefaultInstance<C> {
    /// Store `C::default()` in an empty instance field when its mount node
    /// is entered.
    ///
    /// An instance field that already holds an instance keeps it. A
    /// persistent field keeps its value unchanged.
    fn fill_default(&mut self);
}

impl<C> DefaultInstance<C> for C {
    fn fill_default(&mut self) {}
}

impl<C: Default> DefaultInstance<C> for Option<C> {
    fn fill_default(&mut self) {
        if self.is_none() {
            *self = Some(C::default());
        }
    }
}
